"""Build a static reading record without modifying source papers or experiments."""
from pathlib import Path
from html import escape as e
from urllib.parse import quote
import json
import os

ROOT = Path(__file__).resolve().parent
review = json.loads((ROOT / 'review_notes.json').read_text(encoding='utf-8'))
inventory = {p['id']: p for p in json.loads((ROOT / 'inventory.json').read_text(encoding='utf-8'))}

directions = [
('1. Discover functions in coordinates that expose simple structure',
 'For a mode u(t), compare a direct expression with A(t) cos(phi(t)) and with p(t) cos(psi(t)) + q(t) sin(psi(t)). VGNMD motivates demodulation; coupled splines motivate joint sparse fitting of p and q. A carrier psi removes rapid rotation while p and q describe the remaining slow changes. Unlike amplitude/unwrapped phase, quadrature coordinates do not require dividing by amplitude at zeros. Finite-block analytic-signal estimation and endpoint extensions can still introduce artifacts.',
 'Learn compositions for the envelopes and carrier, rather than choosing a complete function from a fixed family menu. The carrier can itself be a generated expression. Count all carrier constants, envelope constants, knots, boundaries, operators and any stored transform choice. A coordinate change does not guarantee compression: only a lower fully counted description at the same original-waveform error establishes a benefit.',
 'First use the same frozen 40-ms VMD modes. Compare direct, amplitude-phase and quadrature descriptions, with direct fitting retained as an escape route. Test random-phase chirps, amplitude zeros, beating and localized bursts before speech. Measure original mode NMSE, boundary/interior error, size and fit success versus compute. Test shared versus independent envelope knots without transferring the periodic-contour theorem to nonperiodic speech.'),
('2. Learn to repair and compose programs, with a real search teacher',
 'RAG-SR supplies residual-conditioned replacement and an archive of evaluated subexpressions. MDLformer suggests learning which partial expression leaves an easier remaining problem. The current pilot samples complete expressions and only refits their constants; it cannot repair a promising partial result during that search.',
 'Condition an editing model on the IMF, current expression, current reconstruction and residual. Retrieve a useful partial program, edit or replace a subtree, refit constants and retain the measured Pareto front. Train on successful teacher-search trajectories, including failures and near misses, rather than only random synthetic trees. Keep an exploration arm so a learned cost estimate cannot veto unfamiliar structures.',
 'Compare complete-program generation, residual edits, retrieval-only and retrieval-plus-edits under both equal proposals and equal wall time. Freeze the training archive before held-out speakers. Inspect actual error versus cost; do not treat token edit distance, a neural cost estimate or a local solver termination flag as success. A small enumerated grammar subset can provide structural coverage, while constant-fit uncertainty remains separate.'),
('3. Make the representation a simplified graph and share structure where measured useful',
 'The symbolic-regression survey discusses graph representations and reusable subexpressions; exhaustive SR explicitly removes parameter and functional redundancies. The current pilot counts every literal constant plus an output gain, even if an equivalent expression needs fewer independent values.',
 'For example, g times c times sin(wt+b) needs one amplitude product, rather than two independent amplitude values. Apply safe, domain-preserving simplification and common-subexpression sharing before scoring a final payload. For a later whole-block extension, related modes may share a base phase: phi_k(t)=h_k phi_0(t)+delta_k(t). This is an explicit per-block program with shared nodes, not a shared trained waveform decoder.',
 'Compare trees versus simplified trees versus reusable graphs; compare independent modes versus shared-phase graphs. Charge graph topology, references, harmonic multipliers and innovations. Re-evaluate after each rewrite. Do not assume all modes are harmonic or force sharing on unvoiced speech. Keep parameter-count and structural-description axes separate; RVQ is not required for this step.'),
('4. Train decomposition against the cost of its actual reconstructed programs',
 'VMD bandwidth, segmentation masks and downstream separation accuracy are different objectives from compact function reconstruction. A narrowband mode can still need a complicated envelope. Fixed eight-mode decomposition can also spend representation overhead unnecessarily.',
 'After the fitter is reliable, use an alternating objective: D(x, sum_k f_k(t;theta_k)) + mu sum_k ||u_k-f_k||^2 + alpha BW(u) + lambda L(program graph). A learned VMD-like module produces u_k; generated programs f_k reconstruct the output. During a fixed-program step, optimize continuous decomposition and curve parameters. Periodically search, simplify, split, merge or deactivate modes and accept changes based on the actual evaluated description/error front.',
 'Discrete program choices are not differentiable simply because the decomposition is. Start with alternating optimization and measured program costs; use a learned cost surrogate only with periodic exact-search checks. Compare against fixed VMD with the same strengthened fitter, matched total block size, and a direct-waveform program baseline. Charge or omit residuals explicitly, prevent uncharged raw-waveform bypasses, and monitor cancellation between large components and mode collapse.'),
]

parts = ['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">',
 '<title>Local literature review: compact IMF function discovery</title>',
 '<style>body{font:16px/1.6 system-ui,sans-serif;margin:0;color:#192b38;background:#f4f7fa}main{max-width:1100px;margin:auto;padding:32px}h1{line-height:1.15}h2{margin-top:2.2em}h3{line-height:1.3}a{color:#075d91}article,section{background:white;border:1px solid #d5dfe7;border-radius:12px;padding:22px;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:10px;text-align:left;vertical-align:top;border-bottom:1px solid #d5dfe7}th{background:#e6edf3}code{background:#edf3f7;padding:2px 5px}small,.muted{color:#526775}.tag{display:inline-block;background:#e8f2ed;padding:2px 8px;border-radius:6px}nav a{margin-right:14px}.formula{padding:16px;background:#edf3f7;overflow:auto}p{max-width:100ch}@media(max-width:650px){main{padding:14px}table{font-size:12px}td,th{padding:6px}}</style>',
 '<main><p class="tag">Research discussion record | 4 November 2026</p><h1>Compact IMF function discovery</h1>',
 '<p><strong>Recommendation:</strong> improve function discovery on frozen VMD modes first. Then train decomposition to produce modes that the real mathematical representation can describe cheaply.</p>',
 '<p>'+e(review['scope'])+'</p>',
 '<nav><a href="#directions">Proposed directions</a><a href="#audit">Theoretical audit</a><a href="#inventory">All papers</a><a href="#notes">Reading notes</a></nav>',
 '<section><h2>Connection to our completed pilot</h2><p>The held-out pilot covers 64 IMFs. Mean best-found NMSE is 0.8264 for random grammar, 0.6773 after synthetic pretraining and 0.6486 after adaptation. Only 1/64 adapted results reaches NMSE 0.01. These are finite-search results, not a limit on representability. Equal proposal counts also do not imply equal wall time.</p>',
 '<p>Code inspection confirms: whole-expression MLP/GRU proposals, no residual-conditioned structural edits, a finite elementary grammar, bounded float64 local constant fitting, a separately counted output gain, and no reusable expression graph. The current study excludes the VMD residual and does not establish full-block or perceptual reconstruction. No training or implementation changes were made for this review.</p></section>',
 '<h2 id="directions">Four proposed directions</h2>']
for title, mechanism, design, test in directions:
 parts += ['<article><h3>'+e(title)+'</h3><p>'+e(mechanism)+'</p><p><strong>Our proposed extension. </strong>'+e(design)+'</p><p><strong>Falsifiable experiment. </strong>'+e(test)+'</p></article>']
parts += ['<section><h2>What should count as success?</h2><p>Use size at fixed error and error at fixed size, with coverage across all held-out modes. Report median/tail errors and success fractions, not only the easiest IMF or the mean. For each structure distinguish optimization quality from language/search failure with known-formula controls and stronger refitting. Track total fitting/search time and learned-model training time separately.</p><p>Parameter count is a useful current axis; complete description additionally includes operators, topology, shared references, support/knots and numerical values. Actual bitrates require a declared numeric representation and eventually decoding the encoded values. No RVQ or quantization experiment is proposed for the immediate stage.</p><p>Summing independently fitted mode errors introduces cross terms. Consequently, a good average per-mode NMSE does not certify the best reconstructed block. Evaluate and, where appropriate, jointly refit the summed output while keeping per-mode diagnostics.</p><p>MAPSS is informative about local distortion diagnostics but is not validated as a standalone 40-ms IMF quality score. Its human evidence uses 10-second separated signals, not frame-level judgments. Validate perceptual metrics later on reconstructed speech in consistent context; retain exact sampled error now.</p></section>',
 '<section id="audit"><h2>A mathematical caveat in DAMD</h2><p>This is our derivation, not a claim made by the paper. Theorem II.2 constructs hard disjoint partitions and then calls the resulting objective equivalent to unrestricted VMD. Constructing a feasible hard partition proves reconstruction and gives a restricted family; it does not prove an optimum among overlapping modes.</p>',
 '<p>For one positive-frequency bin with value X, fixed center-distance weights a,b&gt;0, unrestricted mode amplitudes satisfy:</p>',
 '<div class="formula">min a|U1|² + b|U2|², subject to U1+U2=X<br>U1=bX/(a+b), U2=aX/(a+b)<br>Optimal cost = ab|X|²/(a+b) &lt; min(a,b)|X|² (hard assignment)</div>',
 '<p>A discrete three-bin example also separates the global hard optimum from a feasible soft decomposition. At frequencies [1,2,3] with spectral values [1,1,1] and two centers, exhaustive hard-cluster assignments have best cost 0.5. Keeping centers [1.5,3], soft mode values [0.94117647,0.8,0] and [0.05882353,0.2,1] sum exactly to the input and cost 0.43529412. Thus unrestricted soft optimization can beat the best hard partition in this discrete analogue. Common positive-frequency normalization factors do not change the inequality.</p>',
 '<p>Practical implication: treat DAMD as a useful partitioning/initialization proposal, not an interchangeable optimization formulation. The paper itself later distinguishes frequency-domain partitioning from a generative time-domain intrinsic mode model. This caveat does not negate its empirical results.</p></section>',
 '<section><h2>Order of experiments</h2><ol><li>Audit fitting and simplify redundant parameters with fixed modes; establish synthetic controls and practical compute/error curves.</li><li>Compare direct, amplitude-phase and quadrature function discovery, adding residual-conditioned edits and retrieval as independently switchable ablations.</li><li>Evaluate simplified graphs and shared per-block structure against independent programs, with actual original-signal reconstruction.</li><li>Only then alternate learned VMD-like decomposition with actual program fitting and size-aware split/merge decisions.</li></ol><p>The immediate research question remains function generation. Every proposal requires an elementary operator language and bounded computation. Learning composition avoids a menu of complete families; it does not certify the globally shortest function among all possible mathematics.</p></section>',
 '<h2 id="inventory">All 19 supplied PDFs</h2><table><thead><tr><th>ID</th><th>Paper</th><th>Venue / local version</th><th>Year</th><th>PDF pages</th></tr></thead><tbody>']
for paper in review['papers']:
 inv=inventory[paper['id']]
 href=quote(Path(os.path.relpath(ROOT.parents[3]/'documentation/literature'/inv['filename'], ROOT)).as_posix())
 parts += ['<tr><td><a href="#'+paper['id']+'">'+paper['id']+'</a></td><td><a href="'+href+'">'+e(paper['title'])+'</a></td><td>'+e(paper['venue'])+'</td><td>'+e(paper['year'])+'</td><td>'+str(inv['pages'])+'</td></tr>']
parts += ['</tbody></table><h2 id="notes">Paper-by-paper evidence and proposals</h2>']
for paper in review['papers']:
 parts += ['<article id="'+paper['id']+'"><h3>'+paper['id']+' | '+e(paper['title'])+'</h3><p class="muted">'+e(paper['venue']+' | '+paper['year']+' | Focused page references: '+paper['pages'])+'</p>']
 for key,label in [('method','Method'),('evidence','Evidence in the paper'),('limit','Limits for our question'),('proposal','Our proposed transfer')]:
  parts += ['<p><strong>'+label+'. </strong>'+e(paper[key])+'</p>']
 parts += ['<small>Source SHA-256: '+inventory[paper['id']]['sha256']+'</small></article>']
parts += ['<p class="muted">The report contains original summaries and proposed experiments. It does not redistribute the source PDFs. Paper links require the repository papers; the notes themselves use no external scripts or assets. Extracted text, file hashes and page references remain alongside this record. No claim of publication novelty or demonstrated speech gain is made for the proposed combinations.</p></main></html>']
(ROOT / 'discussion.html').write_text('\n'.join(parts), encoding='utf-8')
print(ROOT / 'discussion.html')
